import{_ as d,o as e,c as o,ah as r}from"./chunks/framework.BTO5-XmS.js";import"./chunks/theme.CryyyygB.js";const u=JSON.parse('{"title":"笔记方法七合一","description":"","frontmatter":{"title":"笔记方法七合一","abstract":"闪念、文献、永久、原子、MOC、常青、卡片盒七种笔记方法的角色分工，以学 RAG 与 Code Review 两个场景演示从捕获到沉淀的完整流转。","created":"2026-07-08T00:00:00.000Z","tags":["知识管理","笔记方法","学习方法"],"type":"概念解释","related":null,"reference":null,"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/笔记方法七合一.md","filePath":"vault/Knowledge/Methods/笔记方法七合一.md","lastUpdated":1790655645000}'),a={name:"vault/Knowledge/Methods/笔记方法七合一.md"};function n(i,t,l,c,h,g){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="笔记方法七合一" tabindex="-1">笔记方法七合一 <a class="header-anchor" href="#笔记方法七合一" aria-label="Permalink to “笔记方法七合一”">​</a></h1><h2 id="一句话概要" tabindex="-1">一句话概要 <a class="header-anchor" href="#一句话概要" aria-label="Permalink to “一句话概要”">​</a></h2><p>七种笔记方法（闪念笔记、文献笔记、永久笔记、原子笔记、MOC、常青笔记、卡片盒笔记）各有角色。核心原则：<strong>Knowledge 三领域（AI / Engineering / Methods）管&quot;放哪里&quot;，笔记方法管&quot;怎么流转&quot;</strong>。</p><p>以下两个场景演示从原料到知识树的完整流程。</p><h2 id="场景一-学-rag-→-knowledge-ai" tabindex="-1">场景一：学 RAG → Knowledge/AI/ <a class="header-anchor" href="#场景一-学-rag-→-knowledge-ai" aria-label="Permalink to “场景一：学 RAG → Knowledge/AI/”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>笔记方法</th><th>具体动作</th><th>存放位置</th></tr></thead><tbody><tr><td>① 捕获</td><td>闪念笔记</td><td>突然想到「chunk太小丢上下文，太大稀释语义」，10秒丢进 Inbox</td><td><code>Inbox/</code></td></tr><tr><td>① 捕获</td><td>文献笔记</td><td>读《RAG Survey》时的要点摘录，标注原文 URL</td><td><code>Resources/</code></td></tr><tr><td>② 精炼</td><td>永久笔记 = 原子笔记</td><td>「RAG分块策略权衡」用自己的话写，一个笔记只讲一个概念，加 <code>[[嵌入向量]]</code> <code>[[召回率]]</code> 链接</td><td>—</td></tr><tr><td>③ 存储</td><td>（按分类映射表归位）</td><td>判定归属后放入对应目录</td><td><code>Knowledge/AI/</code></td></tr><tr><td>④ 组织</td><td>MOC = 专题聚合页</td><td>分块、嵌入、检索、重排、生成等笔记积累 3 篇以上后，创建「RAG技术专题聚合页」</td><td><code>Knowledge/AI/</code></td></tr><tr><td>⑤ 演进</td><td>常青笔记</td><td>项目实战发现长文本需递归分块，回来更新原笔记补充案例</td><td>原地更新</td></tr><tr><td>全程</td><td>卡片盒笔记</td><td>每篇笔记的 wikilink 互相连接，构成可发现的知识图谱</td><td>—</td></tr></tbody></table><h2 id="场景二-学-code-review-→-knowledge-engineering" tabindex="-1">场景二：学 Code Review → Knowledge/Engineering/ <a class="header-anchor" href="#场景二-学-code-review-→-knowledge-engineering" aria-label="Permalink to “场景二：学 Code Review → Knowledge/Engineering/”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>笔记方法</th><th>具体动作</th><th>存放位置</th></tr></thead><tbody><tr><td>① 捕获</td><td>闪念笔记</td><td>「review 应该关注逻辑而非格式」，顺手记下</td><td><code>Inbox/</code></td></tr><tr><td>① 捕获</td><td>文献笔记</td><td>读 Google Code Review Guide 摘录要点，标注 URL</td><td><code>Resources/</code></td></tr><tr><td>② 精炼</td><td>永久笔记 = 原子笔记</td><td>「Code Review 核心原则」用自己的话写，链接 <code>[[反馈技巧]]</code> <code>[[团队协作]]</code></td><td>—</td></tr><tr><td>③ 存储</td><td>（按分类映射表归位）</td><td>判定归属后放入对应目录</td><td><code>Knowledge/Engineering/</code></td></tr><tr><td>④ 组织</td><td>MOC = 专题聚合页</td><td>「团队能力聚合页」聚合 Review、需求对齐、敏捷协作等笔记</td><td><code>Knowledge/Engineering/</code></td></tr><tr><td>⑤ 演进</td><td>常青笔记</td><td>一次激烈 review 讨论后，回来补充&quot;冲突处理&quot;要点，笔记持续生长</td><td>原地更新</td></tr></tbody></table><h2 id="关键原则" tabindex="-1">关键原则 <a class="header-anchor" href="#关键原则" aria-label="Permalink to “关键原则”">​</a></h2><ul><li><strong>步骤不可跳</strong>：闪念→文献→永久，形成&quot;捕获→消化→沉淀&quot;的闭环</li><li><strong>领域不可混</strong>：AI 相关入 <code>Knowledge/AI/</code>，工程相关入 <code>Knowledge/Engineering/</code>，思维方法入 <code>Knowledge/Methods/</code></li><li><strong>链接不可省</strong>：每篇永久笔记至少链接 2 篇相关笔记，构成卡片盒网络</li><li><strong>常青不可懒</strong>：高频引用的笔记定期回访打磨，保持&quot;生长&quot;而非&quot;完成&quot;</li></ul>',10)])])}const _=d(a,[["render",n]]);export{u as __pageData,_ as default};
